<script setup>
import {computed,ref} from 'vue'
const page=ref('首頁'), section=ref('今日任務'), show=ref(''), name=ref('雲朵旅人'), points=ref(24), partnerPoints=ref(18)
const tabs=[['☁️','首頁'],['🐶','任務'],['⭐','集點卡'],['🪽','紀錄'],['🎁','兌換']]
const tasks=ref([{title:'幫對方買一杯喜歡的飲料',note:'今天想喝微糖珍珠奶茶 ☁️',kind:'臨時發布',points:5,status:'open'},{title:'今天記得好好吃早餐',note:'不可以空著肚子出門喔！',kind:'每日任務',points:3,status:'open'},{title:'一起挑一部週末要看的電影',note:'選好就傳給我吧 🎬',kind:'限期任務',points:7,status:'review'}])
const rewards=ref([{title:'指定一部電影之夜',points:35,emoji:'🎬'},{title:'早餐由我來準備',points:25,emoji:'🥞'},{title:'一個大大的擁抱',points:15,emoji:'🫂'}])
const title=computed(()=>page.value==='任務'?'任務小天地':page.value==='集點卡'?'我們的集點卡':page.value==='紀錄'?'一路走來的紀錄':page.value==='兌換'?'喜歡的兌換所':'今天也一起加油。')
const shown=computed(()=>section.value==='今日任務'?tasks.value.filter(t=>t.status==='open'||t.status==='rejected'):section.value==='驗收任務'?tasks.value.filter(t=>t.status==='review'):tasks.value)
function done(t){if(t.status==='rejected'){t.status='open';return}t.roll=t.random?Math.floor(Math.random()*11):t.points;t.status='review';show.value='dice';setTimeout(()=>show.value='',1700)}
function publish(){if(!draft.value.trim())return;tasks.value.unshift({title:draft.value,note:'一件小小的心意，等你完成。',kind:'臨時發布',points:5,status:'open'});draft.value='';show.value='';section.value='發布任務'}
const draft=ref('')
</script>
<template>
<div class="app"><header><div class="brand"><span>☁️</span><div><b>雲朵日常</b><small>our little cloud</small></div></div><div class="tagline">♥　把喜歡藏進每天的小事裡　♥</div><button class="login" @click="show='login'">登入 / 註冊</button></header>
<main><aside class="side"><div class="couple"><span class="face">你</span><span class="face pink">♡</span><div><b>我們的小宇宙</b><small>兩顆心，住在同一片雲裡</small></div></div><div class="caption">OUR LITTLE SPACE</div><button v-for="([icon,t]) in tabs" :class="{selected:page===t}" @click="page=t"><span class="navicon">{{icon}}</span><span><b>{{t}}</b><small>{{t==='任務'?'一起完成小事':t==='集點卡'?'把喜歡存起來':t==='兌換'?'讓點數變成驚喜':t==='紀錄'?'一路走來的回憶':'我們的日常'}}</small></span></button><div class="quote">you are my<br>favorite person. <small>— every little day</small></div></aside>
<section class="content"><div class="eyebrow">✦　OUR LITTLE SPACE</div><h1>{{title}} <span>☁️</span></h1><p class="sub">{{page==='首頁'?'每一個小小任務，都是偷偷說喜歡的方式。':'把想為彼此做的事，一件一件放進日常。'}}</p>
<template v-if="page==='首頁'"><div class="hero"><div><small>✦ OUR LITTLE ROUTINE ✦</small><h2>喜歡，不只說說而已。<br><em>我們把它做成日常。</em></h2><p>一杯記得的飲料、一句晚安，還有好多為彼此用心的小事。</p><button class="primary" @click="page='任務';show='publish'">發布一個小任務　＋</button></div><div class="pup">🐶<span>☁️</span></div></div><div class="metrics"><button @click="page='任務'"><small>今天的小任務</small><b>{{tasks.filter(t=>t.status==='open').length}} 件</b><i>一起慢慢完成　›</i></button><button @click="page='任務';section='驗收任務'"><small>等待愛的驗收</small><b>{{tasks.filter(t=>t.status==='review').length}} 件</b><i>給對方一個回應　›</i></button><button @click="page='集點卡'"><small>你的專屬點數</small><b>{{points}} pt</b><i>對方有 {{partnerPoints}} 點　›</i></button></div><div class="note">「最喜歡的日常，是每一件事都有你。」 <small>一張來自雲朵的小紙條　♡</small></div></template>
<template v-else-if="page==='任務'"><div class="bar"><div class="seg"><button v-for="s in ['今日任務','發布任務','驗收任務']" :class="{on:section===s}" @click="section=s">{{s}} <span v-if="s==='驗收任務'">{{tasks.filter(t=>t.status==='review').length||''}}</span></button></div><button class="primary" @click="show='publish'">＋ 發布新任務</button></div><article v-for="(t,i) in shown" class="task"><div class="number">0{{i+1}}<hr>♡</div><div class="tasktext"><small>{{t.kind}}　·　今天發布</small><h3>{{t.title}}</h3><p>{{t.note}}</p><span class="from">♡　小熊的心意</span></div><div class="reward"><b>{{t.roll??t.points}}</b><small>POINTS</small></div><button v-if="t.status==='review'" class="complete" @click="show='review'">驗收任務</button><button v-else class="complete" @click="done(t)">{{t.status==='rejected'?'我知道了':'✓ 我完成了'}}</button></article><div v-if="!shown.length" class="empty">☁️<h3>這片雲還空空的呢</h3><p>發布一個小任務，讓今天多一件期待。</p></div></template>
<template v-else-if="page==='集點卡'"><div class="points"><small>YOUR LITTLE TREASURE</small><b>{{points}}<i>pt</i></b><p>這些點數是你用溫柔換來的 ✧</p></div><div class="balances"><div>🌤️ {{name}}<b>{{points}} pt</b></div><div>🌷 小熊<b>{{partnerPoints}} pt</b></div></div><div class="note">每一份用心，都會變成一顆小星星 ✨</div></template>
<template v-else-if="page==='紀錄'"><div class="bar"><div class="seg"><button class="on">全部</button><button>任務</button><button>點數</button><button>兌換</button></div><small>↕ 最新在前</small></div><article class="history" v-for="r in ['完成了「記得帶傘出門」　＋3','收到任務獎勵　＋5','兌換「一個大大的擁抱」　−15']">✧　{{r}} <small>今天・雲朵日常</small></article></template>
<template v-else><div class="banner">☁️　每份禮物都由另一半確認，點數才會正式扣除喔。</div><div class="rewards"><article v-for="r in rewards"><div class="rewardart">{{r.emoji}}</div><h3>{{r.title}}</h3><small>✦ {{r.points}} 點</small><button class="complete" @click="show='redeem'">送出兌換　›</button></article><button class="add" @click="show='newreward'">＋<small>新增一個小願望</small></button></div></template>
</section><aside class="right"><small>OUR CLOUD JOURNAL</small><div class="calendar">October<strong>29</strong>星期四</div><div class="thought">TODAY'S LITTLE THOUGHT<p>有你一起，<br>普通的日子<br>也亮亮的。</p>— by a cloud ☁</div><div class="pup sidepup">🐶</div><div class="rightstats">今天待完成 <b>{{tasks.filter(t=>t.status==='open').length}}</b><hr>等待驗收 <b>{{tasks.filter(t=>t.status==='review').length}}</b></div><button class="invite" @click="show='pair'">💌　邀請另一半</button></aside></main>
<nav class="mobile-nav"><button v-for="([icon,t]) in tabs" :class="{selected:page===t}" @click="page=t"><span>{{icon}}</span>{{t}}</button></nav>
<div v-if="show" class="overlay" @click.self="show=''"><section class="dialog"><button class="close" @click="show=''">×</button><div class="dialog-icon">{{show==='dice'?'🎲':show==='login'?'☁️':show==='pair'?'💌':show==='review'?'✨':show==='publish'?'📝':'🎁'}}</div><small>YOUR LITTLE CLOUD</small><h2>{{show==='dice'?'任務完成！':show==='login'?'回到你們的小宇宙':show==='pair'?'邀請另一半一起來':show==='review'?'任務完成驗收':show==='publish'?'發布一個小任務':'一個小願望'}}</h2><template v-if="show==='publish'"><input v-model="draft" placeholder="任務名稱，例如：幫我買草莓牛奶"><textarea placeholder="給對方的小紙條…"></textarea><select><option>臨時發布</option><option>每天固定（台灣時間 12:00 更新）</option><option>有期限（到期日隔天 00:00 過期）</option></select><label>完成獎勵　<input type="radio" checked name="award"> 固定點數　<input type="radio" name="award"> 0–10 隨機🎲</label><button class="primary wide" @click="publish">發布給另一半</button></template><template v-else-if="show==='dice'"><div class="die">🎲 <b>5</b> pt</div><p>抽出的點數會在發布者驗收後送達。</p><button class="primary wide" @click="show=''">好期待！ ♡</button></template><template v-else-if="show==='review'"><p>驗收完成後，獎勵點數就會送給對方。</p><button class="primary wide" @click="show='';points+=5">✓ 驗收並送出點數</button><textarea placeholder="駁回原因（駁回後會退回今日任務）"></textarea></template><template v-else-if="show==='login'"><input placeholder="Email"><input placeholder="密碼" type="password"><button class="primary wide" @click="show=''">登入 / 建立帳號</button><p>Firebase 尚未連線，現在先逛展示介面。</p></template><template v-else-if="show==='pair'"><p>邀請碼有效 7 天，另一半使用後立即失效。</p><button class="primary wide" @click="show='login'">登入後開始配對</button></template><template v-else><input placeholder="獎勵名稱"><input placeholder="所需點數"><button class="primary wide" @click="show=''">送出申請，等待另一半確認</button></template></section></div>
</div>
</template>
